12	/**
13	 * In-admin webmail for the company mailboxes (admin@, support@, santino@, …).
14	 * Reuses the exact same MailClient customers use for business email, but stays
15	 * entirely inside the admin portal — no jump to the customer side. Reading works
16	 * because resolveMailbox has a staff-only branch that resolves CompanyMailboxes
17	 * (see lib/mail/imap.ts). ADMIN-only via requireArea("platform").
18	 */
19	export default async function AdminInboxPage({
20	  searchParams,
21	}: {
22	  searchParams: Promise<{ mailbox?: string }>;
23	}) {
24	  await requireArea("platform");
25	  const { mailbox: requested } = await searchParams;
26	
27	  const company = await listCompanyMailboxes();
28	  if (company.length === 0) {
29	    return (
30	      <div className="space-y-6">
31	        <PageHeader title="Company inbox" sub="Read and send from the company mailboxes." />
32	        <div className="card flex flex-col items-center justify-center py-14 text-center">
33	          <h3 className="text-base font-semibold">No mailboxes yet</h3>
34	          <p className="mt-1 max-w-sm text-sm text-slate-400">
35	            Create a company mailbox first, then read its mail here.
36	          </p>
37	          <Link href="/admin/mailboxes" className="btn-primary mt-5">
38	            Manage mailboxes
39	          </Link>
40	        </div>
41	      </div>
42	    );
43	  }
44	
45	  // The switcher shows only the company mailboxes (with their live quota usage).
46	  const mailboxes: MailboxInfo[] = company.map((c) => ({
47	    address: c.address,
48	    usedBytes: (c.usedMB ?? 0) * 1024 * 1024,
49	    quotaBytes: c.quotaMB * 1024 * 1024,
50	  }));
51	
52	  const wanted = requested?.trim().toLowerCase();
53	  const active =
54	    wanted && mailboxes.some((m) => m.address.toLowerCase() === wanted) ? wanted : mailboxes[0].address;
55	
56	  let folders: MailFolder[] = [];
57	  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
58	  let inboxPath = "INBOX";
59	  let failed = false;
60	  try {
61	    folders = await listFolders(active);
62	    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
63	    list = await listMessages(inboxPath, 1, undefined, active);
64	  } catch {
65	    failed = true;
66	  }
67	
68	  if (failed || folders.length === 0) {
69	    return (
70	      <div className="space-y-6">
71	        <PageHeader title="Company inbox" sub={active} />
72	        <div className="card p-6 text-center text-sm text-slate-400">
73	          Couldn&apos;t reach the mail server for <span className="font-medium text-slate-200">{active}</span>.
74	          If the mailbox was just created, give it a moment and reload; otherwise reset its password on the{" "}
75	          <Link href="/admin/mailboxes" className="text-brand-300 hover:underline">
76	            Mailboxes
77	          </Link>{" "}
78	          page.
79	        </div>
80	      </div>
81	    );
82	  }
83	
84	  return (
85	    <div className="h-full">
86	      <MailClient
87	        initialFolders={folders}
88	        initialMailboxes={mailboxes}
89	        initialList={list}
90	        initialFolderPath={inboxPath}
91	        initialActiveAddress={active}
92	        loadMailboxes={listCompanyMailboxInfos}
93	      />
94	    </div>
95	  );
96	}
