1	"use server";
2	
3	/**
4	 * Admin-only management of COMPANY mailboxes on the Nxeon domain (admin@,
5	 * support@, santino@, and any more the admin creates) — free.
6	 *
7	 * These are deliberately decoupled from the customer email-hosting model
8	 * (EmailSubscription / EmailPlan / Mailbox): a company mailbox is a
9	 * `CompanyMailbox` row + a Mailcow mailbox, and nothing else. No wallet debit,
10	 * no plan limit, no subscription — "free" is structural, not a discount.
11	 *
12	 * SECURITY. Every export authenticates with `requireArea("platform")` (ADMIN-only)
13	 * INSIDE the function before touching Mailcow or the database, and returns a typed
14	 * { ok, error? } result rather than throwing raw internals at the client. The
15	 * mailbox password is generated server-side, stored AES-256-GCM encrypted
16	 * (lib/crypto-box), and only ever returned to the admin on explicit reveal/reset.
17	 */
18	import { db } from "./db";
19	import { requireArea } from "./rbac";
20	import { encryptSecret, decryptSecret } from "./crypto-box";
21	import { randomBytes } from "node:crypto";
22	import {
23	  COMPANY_MAIL_DOMAIN,
24	  DEFAULT_COMPANY_LOCALPARTS,
25	  type CompanyMailboxRow,
26	} from "./company-mail-core";
27	import type { MailboxInfo } from "./mail/types";
28	import {
29	  mailcowConfigured,
30	  mcDomainExists,
31	  mcCreateDomain,
32	  mcCreateMailbox,
33	  mcDeleteMailbox,
34	  mcSetMailboxPassword,
35	  mcListMailboxes,
36	  isMailcowUnreachable,
37	} from "./mailcow";
38	
39	/** Default quota for a company mailbox. */
40	const DEFAULT_QUOTA_MB = 2048;
41	
42	type Ok<T> = { ok: true } & T;
43	type Err = { ok: false; error: string };
44	
45	/** Lower-case, validate a local part (the bit before @). */
46	function normalizeLocalPart(raw: string): string | null {
47	  const lp = String(raw ?? "").trim().toLowerCase();
48	  // RFC-ish, conservative: start/end alphanumeric, dots/dashes/underscores inside.
49	  if (!/^[a-z0-9](?:[a-z0-9._-]{0,61}[a-z0-9])?$/.test(lp)) return null;
50	  return lp;
51	}
52	
53	/** A strong, URL-safe mailbox password. */
54	function generatePassword(): string {
55	  return randomBytes(18).toString("base64url");
56	}
57	
58	/** Map an unknown error to a safe, user-facing string. */
59	function safeMailError(err: unknown): string {
60	  if (isMailcowUnreachable(err)) {
61	    return "The mail server is unreachable right now. Please try again shortly.";
62	  }
63	  const msg = err instanceof Error ? err.message : String(err);
64	  // Mailcow "danger" messages are already terse and safe to surface.
65	  return msg && msg.length < 200 ? msg : "The mail server rejected the request.";
66	}
67	
68	/** Ensure the company domain exists in Mailcow (idempotent, best-effort create). */
69	async function ensureDomain(): Promise<void> {
70	  if (await mcDomainExists(COMPANY_MAIL_DOMAIN)) return;
71	  await mcCreateDomain(COMPANY_MAIL_DOMAIN);
72	}
73	
74	async function audit(userId: string, action: string, detail: string): Promise<void> {
75	  try {
76	    await db.auditLog.create({ data: { userId, action, detail } });
77	  } catch {
78	    /* audit is best-effort — never fail the operation on a logging error */
79	  }
80	}
81	
82	/**
83	 * List every company mailbox. Merges live quota usage from Mailcow when it is
84	 * reachable; falls back to DB-only rows (usedMB: null) if it is not.
85	 */
86	export async function listCompanyMailboxes(): Promise<CompanyMailboxRow[]> {
87	  await requireArea("platform");
88	  const rows = await db.companyMailbox.findMany({ orderBy: { address: "asc" } });
89	
90	  const usedByAddress = new Map<string, number>();
91	  try {
92	    if (mailcowConfigured()) {
93	      const live = await mcListMailboxes(COMPANY_MAIL_DOMAIN);
94	      for (const m of live) {
95	        usedByAddress.set(m.address.toLowerCase(), Math.round(m.quotaUsedBytes / (1024 * 1024)));
96	      }
97	    }
98	  } catch {
99	    /* Mailcow unreachable — show DB rows without live usage */
100	  }
101	
102	  return rows.map((r) => ({
103	    id: r.id,
104	    address: r.address,
105	    label: r.label,
106	    quotaMB: r.quotaMB,
107	    status: r.status,
108	    createdAt: r.createdAt.toISOString(),
109	    usedMB: usedByAddress.has(r.address.toLowerCase()) ? usedByAddress.get(r.address.toLowerCase())! : null,
110	  }));
111	}
112	
113	/**
114	 * The company mailboxes as `MailboxInfo` for the admin webmail switcher. This is
115	 * the admin-portal equivalent of the customer `getMailboxes()` — it is what keeps
116	 * company mail OUT of the customer switcher (that one no longer lists them).
117	 * ADMIN-only (delegates to the guarded `listCompanyMailboxes`).
118	 */
119	export async function listCompanyMailboxInfos(): Promise<MailboxInfo[]> {
120	  await requireArea("platform");
121	  const rows = await listCompanyMailboxes();
122	  return rows.map((r) => ({
123	    address: r.address,
124	    usedBytes: (r.usedMB ?? 0) * 1024 * 1024,
125	    quotaBytes: r.quotaMB * 1024 * 1024,
126	  }));
127	}
128	
129	/**
130	 * Create a free company mailbox. Provisions it on Mailcow, stores the encrypted
131	 * password, and returns the generated password ONCE (so the admin can hand it to
132	 * whoever owns the address / sign in to webmail).
133	 */
134	export async function createCompanyMailbox(
135	  localPartRaw: string,
136	  labelRaw?: string
137	): Promise<Ok<{ address: string; password: string }> | Err> {
138	  const admin = await requireArea("platform");
139	  if (!mailcowConfigured()) {
140	    return { ok: false, error: "Mail hosting is not configured (MAILCOW_API_URL / MAILCOW_API_KEY)." };
141	  }
142	  const localPart = normalizeLocalPart(localPartRaw);
143	  if (!localPart) {
144	    return { ok: false, error: "Enter a valid mailbox name (letters, numbers, dots, dashes)." };
145	  }
146	  const address = `${localPart}@${COMPANY_MAIL_DOMAIN}`;
147	
148	  const existing = await db.companyMailbox.findUnique({ where: { address } });
149	  if (existing) return { ok: false, error: `${address} already exists.` };
150	
151	  const label = labelRaw?.trim() ? labelRaw.trim().slice(0, 80) : null;
152	  const password = generatePassword();
153	
154	  try {
155	    await ensureDomain();
156	    await mcCreateMailbox({
157	      localPart,
158	      domain: COMPANY_MAIL_DOMAIN,
159	      name: label ?? localPart,
160	      password,
161	      quotaMB: DEFAULT_QUOTA_MB,
162	    });
163	  } catch (err) {
164	    return { ok: false, error: safeMailError(err) };
165	  }
166	
167	  await db.companyMailbox.create({
168	    data: {
169	      address,
170	      label,
171	      passwordEnc: encryptSecret(password),
172	      quotaMB: DEFAULT_QUOTA_MB,
173	      status: "ACTIVE",
174	      createdById: admin.id,
175	    },
176	  });
177	  await audit(admin.id, "company_mailbox.create", address);
178	
179	  return { ok: true, address, password };
180	}
181	
182	/**
183	 * Create any of the default starter mailboxes (admin@, support@, santino@) that
184	 * don't already exist. Returns the created addresses + their one-time passwords.
185	 */
186	export async function createDefaultCompanyMailboxes(): Promise<
187	  Ok<{ created: Array<{ address: string; password: string }>; skipped: string[] }> | Err
188	> {
189	  await requireArea("platform");
190	  if (!mailcowConfigured()) {
191	    return { ok: false, error: "Mail hosting is not configured (MAILCOW_API_URL / MAILCOW_API_KEY)." };
192	  }
193	  const created: Array<{ address: string; password: string }> = [];
194	  const skipped: string[] = [];
195	  for (const lp of DEFAULT_COMPANY_LOCALPARTS) {
196	    const res = await createCompanyMailbox(lp);
197	    if (res.ok) created.push({ address: res.address, password: res.password });
198	    else skipped.push(`${lp}@${COMPANY_MAIL_DOMAIN}`);
199	  }
200	  return { ok: true, created, skipped };
201	}
202	
203	/** Reveal an existing mailbox's stored password (decrypted). */
204	export async function revealCompanyMailboxPassword(
205	  id: string
206	): Promise<Ok<{ address: string; password: string }> | Err> {
207	  const admin = await requireArea("platform");
208	  const box = await db.companyMailbox.findUnique({ where: { id } });
209	  if (!box) return { ok: false, error: "Mailbox not found." };
210	  const password = decryptSecret(box.passwordEnc);
211	  if (!password) return { ok: false, error: "No stored password for this mailbox." };
212	  await audit(admin.id, "company_mailbox.reveal", box.address);
213	  return { ok: true, address: box.address, password };
214	}
215	
216	/** Reset a mailbox password to a new strong value; returns it once. */
217	export async function resetCompanyMailboxPassword(
218	  id: string
219	): Promise<Ok<{ address: string; password: string }> | Err> {
220	  const admin = await requireArea("platform");
221	  if (!mailcowConfigured()) return { ok: false, error: "Mail hosting is not configured." };
222	  const box = await db.companyMailbox.findUnique({ where: { id } });
223	  if (!box) return { ok: false, error: "Mailbox not found." };
224	  const password = generatePassword();
225	  try {
226	    await mcSetMailboxPassword(box.address, password);
227	  } catch (err) {
228	    return { ok: false, error: safeMailError(err) };
229	  }
230	  await db.companyMailbox.update({ where: { id }, data: { passwordEnc: encryptSecret(password), status: "ACTIVE" } });
231	  await audit(admin.id, "company_mailbox.reset_password", box.address);
232	  return { ok: true, address: box.address, password };
233	}
234	
235	/** Delete a company mailbox from Mailcow and the database. */
236	export async function deleteCompanyMailbox(id: string): Promise<{ ok: true } | Err> {
237	  const admin = await requireArea("platform");
238	  const box = await db.companyMailbox.findUnique({ where: { id } });
239	  if (!box) return { ok: false, error: "Mailbox not found." };
240	  if (mailcowConfigured()) {
241	    try {
242	      await mcDeleteMailbox(box.address);
243	    } catch (err) {
244	      // If Mailcow refused (not merely unreachable), surface it; don't orphan the row.
245	      if (!isMailcowUnreachable(err)) return { ok: false, error: safeMailError(err) };
246	    }
247	  }
248	  await db.companyMailbox.delete({ where: { id } });
249	  await audit(admin.id, "company_mailbox.delete", box.address);
250	  return { ok: true };
251	}
