1	/**
2	 * Plain (non-"use server") constants + types for company mailboxes, so they can
3	 * be imported by the server action, the admin page, and the client component.
4	 * A "use server" module may only export async functions, so these live here.
5	 */
6	
7	/** The company domain every company mailbox lives on. */
8	export const COMPANY_MAIL_DOMAIN = "nxeon.cloud";
9	
10	/** The starter set the admin asked for (created by "Create default set"). */
11	export const DEFAULT_COMPANY_LOCALPARTS = ["admin", "support", "santino"] as const;
12	
13	export type CompanyMailboxRow = {
14	  id: string;
15	  address: string;
16	  label: string | null;
17	  quotaMB: number;
18	  status: string;
19	  createdAt: string;
20	  /** Live usage from Mailcow when reachable, else null. */
21	  usedMB: number | null;
22	};
