1	// IMAP engine for the native webmail client.
2	//
3	// Plain server-side module (NOT "use server"): it holds the short-lived imapflow
4	// connection helpers, special-use → role mapping, and the mailbox-ownership
5	// resolver shared by the server actions (lib/actions-mail.ts) and the attachment
6	// download route (app/api/mail/attachment/route.ts). Every connection is opened
7	// per-request and always closed. It is never imported into a client bundle.
8	
9	import { ImapFlow } from "imapflow";
10	import type {
11	  FetchMessageObject,
12	  MailboxLockOptions,
13	  MessageAddressObject,
14	  MessageStructureObject,
15	} from "imapflow";
16	import { requireUser } from "@/lib/auth";
17	import { isStaff } from "@/lib/rbac";
18	import { db } from "@/lib/db";
19	import { decryptSecret } from "@/lib/crypto-box";
20	import { COMPANY_MAIL_DOMAIN } from "@/lib/company-mail-core";
21	import { checkRateLimit } from "@/lib/rate-limit";
22	import { mailcowConfigured, mcListMailboxes } from "@/lib/mailcow";
23	import { MAIL_IMAP_HOST, MAIL_IMAP_PORT, type MailAddress, type MailFolderRole } from "./types";
24	import type { User } from "@prisma/client";
25	
26	// mailparser ships no bundled type declarations and its untyped JS module can't
27	// be augmented via `declare module`. Instead we describe the slice we use with
28	// local interfaces and import `simpleParser` with a suppressed-error import,
29	// exposing a single typed `parseMessage` wrapper for the rest of the backend.
30	// @ts-ignore -- mailparser has no type declarations
31	import { simpleParser as _simpleParser } from "mailparser";
32	
33	export interface ParsedAttachment {
34	  type?: string;
35	  partId?: string;
36	  filename?: string;
37	  contentType?: string;
38	  contentDisposition?: string;
39	  size?: number;
40	  content?: Buffer;
41	  cid?: string;
42	  contentId?: string;
43	  related?: boolean;
44	}
45	export interface ParsedMessage {
46	  subject?: string;
47	  from?: { value?: { name?: string; address?: string }[]; text?: string };
48	  to?: unknown;
49	  cc?: unknown;
50	  bcc?: unknown;
51	  date?: Date;
52	  messageId?: string;
53	  inReplyTo?: string;
54	  references?: string | string[];
55	  html?: string | false;
56	  text?: string;
57	  textAsHtml?: string;
58	  attachments: ParsedAttachment[];
59	}
60	
61	const simpleParser = _simpleParser as (
62	  source: Buffer | string,
63	  options?: Record<string, unknown>,
64	) => Promise<ParsedMessage>;
65	
66	/** Parse a raw RFC822 message source into a typed structure (via mailparser). */
67	export async function parseMessage(source: Buffer | string): Promise<ParsedMessage> {
68	  return simpleParser(source);
69	}
70	
71	/** The TLS servername the mail server's certificate is issued for. */
72	export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";
73	
74	/**
75	 * TLS options for every webmail connection to the mail server (IMAP 993 and
76	 * SMTP submission 587). Shared so the two cannot drift apart.
77	 *
78	 * WHY VERIFICATION IS ON. We connect by internal IP (10.20.0.10) while the
79	 * server presents a public certificate for `mail.nxeon.cloud`, so a bare
80	 * connection fails on the name mismatch. The previous code resolved that by
81	 * setting `rejectUnauthorized: false` — which does not just tolerate the name
82	 * mismatch, it accepts ANY certificate from anything answering on that address.
83	 * The very first thing sent over that session is the customer's mailbox password
84	 * (IMAP LOGIN / SMTP AUTH), so anyone able to answer on the NAT bridge could
85	 * have harvested every mailbox credential on the platform, and nothing would
86	 * have looked wrong. `servername` alone is the correct fix: it sets SNI *and*
87	 * the name validation is performed against, so the real certificate verifies.
88	 *
89	 * MEASURED, not assumed (2026-07-27, from the app host):
90	 *   openssl s_client -connect 10.20.0.10:993 -servername mail.nxeon.cloud \
91	 *     -verify_return_error   ->  CN=mail.nxeon.cloud, "Verification: OK"
92	 *   …and the same on :587 with -starttls smtp.
93	 *
94	 * `MAIL_TLS_INSECURE=1` is a documented break-glass for an operator whose
95	 * certificate has genuinely expired mid-incident: it restores the old behaviour
96	 * from `.env` without a code change. It defaults OFF, so the safe state is the
97	 * one you get by doing nothing — the opposite of what it replaces.
98	 */
99	export function mailTlsOptions(): { servername: string; rejectUnauthorized: boolean } {
100	  return {
101	    servername: MAIL_TLS_SERVERNAME,
102	    rejectUnauthorized: process.env.MAIL_TLS_INSECURE !== "1",
103	  };
104	}
105	
106	/** Minimal credential shape needed to authenticate an IMAP/SMTP session. */
107	export type MailboxCredentials = { address: string; password: string };
108	
109	/** The sender identity the customer configured, applied to every outgoing message. */
110	export type MailboxIdentity = {
111	  displayName: string | null;
112	  replyTo: string | null;
113	  organization: string | null;
114	};
115	
116	/** The subscription context a mailbox hangs off, for verification-aware guards. */
117	export type ResolvedSubscription = {
118	  id: string;
119	  domainName: string;
120	  external: boolean;
121	  verified: boolean;
122	  status: string;
123	};
124	
125	/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
126	export type ResolvedMailbox = {
127	  user: User;
128	  mailboxId: string;
129	  address: string;
130	  quotaMB: number | null;
131	  cred: MailboxCredentials;
132	  identity: MailboxIdentity;
133	  subscription: ResolvedSubscription;
134	};
135	
136	/**
137	 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
138	 *
139	 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
140	 * the mail server — or one whose row was lost — was invisible in the portal even
141	 * though real mail was landing in it ("its not detecting the mailbox that i
142	 * already have on this account"). This reconciles the two.
143	 *
144	 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
145	 * a way to acquire someone else's mailbox:
146	 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
147	 *   2. Only subscriptions with `verified === true` are eligible. Owning a
148	 *      subscription ROW is not proof of owning the DOMAIN — an unverified
149	 *      external subscription is just a claim, and adopting on a claim would
150	 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
151	 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
152	 *      already has a row, so a mailbox another tenant legitimately holds is
153	 *      never re-pointed at this user.
154	 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
155	 *      customer is told to reset it — adoption grants visibility, not access.
156	 *
157	 * Never throws: a Mailcow outage must not turn the mail page into an error.
158	 * Returns the number of rows created.
159	 */
160	export async function discoverMailboxes(userId: string): Promise<number> {
161	  if (!mailcowConfigured()) return 0;
162	
163	  // Guard against hammering Mailcow: the mail page calls this on every load for
164	  // an account with no mailbox, which is exactly the account that reaches here.
165	  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
166	  if (!gate.ok) return 0;
167	
168	  const subs = await db.emailSubscription.findMany({
169	    where: { userId, status: { not: "CANCELLED" }, verified: true },
170	    select: { id: true, domainName: true },
171	  });
172	  if (subs.length === 0) return 0;
173	
174	  let created = 0;
175	  for (const sub of subs) {
176	    const domain = sub.domainName.trim().toLowerCase();
177	    if (!domain) continue;
178	
179	    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
180	    try {
181	      remote = await mcListMailboxes(domain);
182	    } catch (e) {
183	      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
184	      continue;
185	    }
186	    if (remote.length === 0) continue;
187	
188	    const existing = await db.mailbox.findMany({
189	      where: { address: { in: remote.map((m) => m.address) } },
190	      select: { address: true },
191	    });
192	    const known = new Set(existing.map((m) => m.address.toLowerCase()));
193	
194	    for (const m of remote) {
195	      if (known.has(m.address)) continue;
196	      try {
197	        await db.mailbox.create({
198	          data: {
199	            subscriptionId: sub.id,
200	            address: m.address,
201	            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
202	            status: m.active ? "ACTIVE" : "SUSPENDED",
203	            displayName: m.name && m.name !== m.address ? m.name : null,
204	          },
205	        });
206	        created++;
207	      } catch {
208	        // Unique-violation race (two tabs discovering at once) — the row exists
209	        // now either way, which is the outcome we wanted.
210	      }
211	    }
212	  }
213	
214	  if (created > 0) {
215	    await db.auditLog
216	      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
217	      .catch(() => {});
218	  }
219	  return created;
220	}
