222	/**
223	 * Why the caller can't open webmail, so the UI can say what is actually wrong
224	 * instead of one catch-all "No mailbox connected".
225	 */
226	export type MailAccessState =
227	  | { kind: "ok"; address: string }
228	  | { kind: "no-subscription" }
229	  | { kind: "unverified-domain"; domains: string[] }
230	  | { kind: "no-mailbox"; domains: string[] }
231	  | { kind: "no-password"; address: string }
232	  | { kind: "server-unreachable"; address: string };
