234	/**
235	 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
236	 * that only exists on the server is found before we declare there is none.
237	 */
238	export async function mailAccessState(userId: string): Promise<MailAccessState> {
239	  await discoverMailboxes(userId).catch(() => 0);
240	
241	  const subs = await db.emailSubscription.findMany({
242	    where: { userId, status: { not: "CANCELLED" } },
243	    select: { domainName: true, verified: true, external: true },
244	  });
245	  if (subs.length === 0) return { kind: "no-subscription" };
246	
247	  const boxes = await db.mailbox.findMany({
248	    where: { subscription: { userId } },
249	    orderBy: { createdAt: "asc" },
250	    select: { address: true, passwordEnc: true },
251	  });
252	
253	  if (boxes.length === 0) {
254	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
255	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
256	    // An unverified domain is the more actionable problem: no mailbox can even
257	    // be created on it yet, so lead with that.
258	    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
259	    return { kind: "no-mailbox", domains: verified };
260	  }
261	
262	  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
263	  if (!withPassword) return { kind: "no-password", address: boxes[0].address };
264	
265	  // A mailbox and a credential exist, so the page's failure was the mail server
266	  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
267	  return { kind: "server-unreachable", address: withPassword.address };
268	}
