270	/**
271	 * Resolve the mailbox a request may act on. Requires an authenticated user,
272	 * loads only mailboxes belonging to that user's email subscriptions, and (when
273	 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
274	 * credential; throws a friendly error if the password was never captured.
275	 *
276	 * NEVER returns a mailbox the caller does not own.
277	 */
278	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
279	  const user = await requireUser();
280	
281	  // --- Staff-only: read COMPANY mailboxes (admin@, support@, …) in-portal. ---
282	  // This is an ADDITIVE branch: it only runs for staff, so the customer
283	  // resolution below is completely unchanged. A company mailbox is synthesized
284	  // into the same ResolvedMailbox shape (no EmailSubscription backing it).
285	  if (isStaff(user.role)) {
286	    const wantedLc = mailboxAddress?.trim().toLowerCase();
287	    const synthesize = (c: {
288	      id: string;
289	      address: string;
290	      label: string | null;
291	      passwordEnc: string;
292	      quotaMB: number;
293	      status: string;
294	    }): ResolvedMailbox => {
295	      const password = decryptSecret(c.passwordEnc);
296	      if (!password) throw new Error("Reset this mailbox's password to enable webmail access.");
297	      return {
298	        user,
299	        mailboxId: `company:${c.id}`,
300	        address: c.address,
301	        quotaMB: c.quotaMB,
302	        cred: { address: c.address, password },
303	        identity: { displayName: c.label, replyTo: null, organization: null },
304	        subscription: {
305	          id: `company:${c.id}`,
306	          domainName: COMPANY_MAIL_DOMAIN,
307	          external: false,
308	          verified: true,
309	          status: c.status,
310	        },
311	      };
312	    };
313	    // Only resolve an EXPLICITLY requested company address (the admin inbox always
314	    // passes one). With no address, fall through to the customer path — so a
315	    // staffer's own /dashboard/mail never silently lands on a company mailbox.
316	    if (wantedLc) {
317	      const c = await db.companyMailbox.findUnique({ where: { address: wantedLc } });
318	      if (c) return synthesize(c);
319	      // Not a company address — fall through to the customer path below.
320	    }
321	  }
322	
323	  const load = () =>
324	    db.mailbox.findMany({
325	      where: { subscription: { userId: user.id } },
326	      include: { subscription: true },
327	      orderBy: { createdAt: "asc" },
328	    });
329	
330	  let boxes = await load();
331	  const wanted = mailboxAddress?.trim().toLowerCase();
332	
333	  // A miss here used to be terminal, which is how a mailbox that exists on the
334	  // mail server but has no local row became "you do not have a mailbox yet".
335	  // Reconcile against Mailcow (verified domains only) before giving that answer.
336	  if (boxes.length === 0 || (wanted && !boxes.some((b) => b.address.toLowerCase() === wanted))) {
337	    if (await discoverMailboxes(user.id).catch(() => 0)) boxes = await load();
338	  }
339	
340	  if (boxes.length === 0) {
341	    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
342	  }
343	
344	  let box = boxes[0];
345	  if (wanted) {
346	    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
347	    if (!match) throw new Error("You do not have access to that mailbox.");
348	    box = match;
349	  }
350	
351	  const password = decryptSecret(box.passwordEnc);
352	  if (!password) {
353	    throw new Error("Please reset your mailbox password first to enable webmail access.");
354	  }
355	
356	  return {
357	    user,
358	    mailboxId: box.id,
359	    address: box.address,
360	    quotaMB: box.quotaMB ?? null,
361	    cred: { address: box.address, password },
362	    identity: {
363	      displayName: box.displayName,
364	      replyTo: box.replyTo,
365	      organization: box.organization,
366	    },
367	    subscription: {
368	      id: box.subscription.id,
369	      domainName: box.subscription.domainName,
370	      external: box.subscription.external,
371	      verified: box.subscription.verified,
372	      status: box.subscription.status,
373	    },
374	  };
375	}
