377	/** Build a per-request imapflow client for the given credential. */
378	export function createImapClient(cred: MailboxCredentials): ImapFlow {
379	  return new ImapFlow({
380	    host: MAIL_IMAP_HOST,
381	    port: MAIL_IMAP_PORT,
382	    secure: true,
383	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
384	    // and validation servername so TLS verifies against the right name.
385	    servername: MAIL_TLS_SERVERNAME,
386	    tls: mailTlsOptions(),
387	    auth: { user: cred.address, pass: cred.password },
388	    logger: false,
389	    disableAutoIdle: true,
390	  });
391	}
