523	/** Best-effort ISO date string from an imapflow fetch result. */
524	export function isoDate(msg: Pick<FetchMessageObject, "envelope" | "internalDate">): string {
525	  const d = msg.envelope?.date || (msg.internalDate ? new Date(msg.internalDate) : undefined);
526	  const date = d instanceof Date ? d : d ? new Date(d) : new Date(0);
527	  return Number.isNaN(date.getTime()) ? new Date(0).toISOString() : date.toISOString();
528	}
